<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">scheduler</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PNDMScheduler.from_pretrained(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;runwayml/stable-diffusion-v1-5&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, subfo</span></span>
